{
  "name": "temperature-converter",
  "version": "1.0.0",
  "description": "A small browser-based temperature converter (Node.js 22 application).",
  "type": "module",
  "private": true,
  "engines": {
    "node": ">=22"
  },
  "scripts": {
    "start": "node source/index.js",
    "test": "node --test",
    "build": "node --check source/convert.js && node --check source/app.js && node --check source/index.js"
  }
}

// HTTP application layer (FR1, FR2, FR4, FR5).
//
// Exposes:
//   - createApp(): an http server whose request handler routes:
//       GET  /            -> static HTML page (public/index.html)
//       POST /api/convert -> JSON conversion endpoint (FR2, FR4)
//       GET  /health      -> { status: "ok" } (FR5)
//   - handler(req, res):  the underlying request handler (separated from the
//     server for easier testing).
//
// The pure conversion/validation logic lives in convert.js and is kept free of
// any HTTP dependency (NFR1).

import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { convert, validate } from './convert.js';

const __dirname = dirname(fileURLToPath(import.meta.url));
const INDEX_HTML_PATH = join(__dirname, '..', 'public', 'index.html');

// A small HTTP error type used internally to carry status and JSON body.
class HttpError extends Error {
  constructor(status, message) {
    super(message);
    this.status = status;
  }
}

function sendJson(res, status, body) {
  const payload = JSON.stringify(body);
  res.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(payload),
  });
  res.end(payload);
}

/**
 * Read and validate the "value", "from" and "to" fields from a parsed JSON
 * body. Throws HttpError(400) for every invalid case described in FR4.
 */
function validateBody(body) {
  if (body === null || typeof body !== 'object' || Array.isArray(body)) {
    throw new HttpError(400, 'request body must be a JSON object');
  }
  const { value, from, to } = body;
  if (value === undefined || from === undefined || to === undefined) {
    throw new HttpError(400, 'value, from and to are required');
  }
  const error = validate(value, from, to);
  if (error !== null) {
    throw new HttpError(400, error);
  }
  return { value, from, to };
}

/**
 * Parse the raw request body. Rejects non-JSON bodies with a 400 error, and
 * enforces a maximum size to avoid unbounded allocation.
 */
function readJsonBody(req) {
  return new Promise((resolve, reject) => {
    let size = 0;
    const chunks = [];
    const MAX_BODY_BYTES = 64 * 1024;

    req.on('data', (chunk) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        reject(new HttpError(400, 'request body too large'));
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => {
      const raw = Buffer.concat(chunks).toString('utf8');
      if (raw.trim() === '') {
        reject(new HttpError(400, 'request body is empty JSON'));
        return;
      }
      let parsed;
      try {
        parsed = JSON.parse(raw);
      } catch {
        reject(new HttpError(400, 'malformed JSON'));
        return;
      }
      resolve(parsed);
    });
    req.on('error', (err) => {
      reject(new HttpError(400, 'error reading request body: ' + err.message));
    });
  });
}

/**
 * The HTTP request handler. Routes GET /, POST /api/convert and GET /health.
 */
export async function handler(req, res) {
  const method = req.method ?? 'GET';
  const url = new URL(req.url ?? '/', 'http://localhost');

  try {
    if (method === 'GET' && url.pathname === '/') {
      const html = await readFile(INDEX_HTML_PATH, 'utf8');
      res.writeHead(200, {
        'Content-Type': 'text/html; charset=utf-8',
        'Content-Length': Buffer.byteLength(html),
      });
      res.end(html);
      return;
    }

    if (method === 'GET' && url.pathname === '/health') {
      sendJson(res, 200, { status: 'ok' });
      return;
    }

    if (method === 'POST' && url.pathname === '/api/convert') {
      const body = await readJsonBody(req);
      const { value, from, to } = validateBody(body);
      const result = convert(value, from, to);
      sendJson(res, 200, { value: result, unit: to });
      return;
    }

    // Unknown route/method combination.
    sendJson(res, 404, { error: 'not found' });
  } catch (err) {
    if (err instanceof HttpError) {
      sendJson(res, err.status, { error: err.message });
      return;
    }
    sendJson(res, 500, { error: 'internal server error' });
  }
}

/**
 * Create and return an http.Server wired to {handler}.
 */
export function createApp() {
  return createServer(handler);
}

// Pure temperature conversion and validation module.
// No HTTP or I/O dependency: this module is fully self-contained (NFR1).

// Absolute zero boundaries for each supported unit (FR4).
export const ABSOLUTE_ZERO = Object.freeze({
  C: -273.15,
  F: -459.67,
  K: 0,
});

// Supported units.
export const UNITS = Object.freeze(['C', 'F', 'K']);

// Tolerance for insignificant floating-point error at the absolute-zero
// boundaries described in FR4.
const EPSILON = 1e-9;

/**
 * Validate a value/from/to triple. Returns an error message string when the
 * triple is invalid, or null when it is valid.
 *
 * - value must be a finite number (rejects missing, booleans, strings, NaN,
 *   and infinities).
 * - from and to must be one of C, F, K.
 * - value must not be below absolute zero for the `from` unit (FR4), allowing
 *   insignificant floating-point error at the exact boundary.
 */
export function validate(value, from, to) {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    return 'value must be a number';
  }
  if (typeof from !== 'string' || !UNITS.includes(from)) {
    return 'unsupported source unit';
  }
  if (typeof to !== 'string' || !UNITS.includes(to)) {
    return 'unsupported destination unit';
  }
  // Allow insignificant floating-point error at the boundary (FR4).
  if (value < ABSOLUTE_ZERO[from] - EPSILON) {
    return 'temperature below absolute zero';
  }
  return null;
}

/**
 * Convert a temperature value from one unit to another (FR3).
 *
 * Throws an Error with a nonempty message when the input is invalid
 * (see {validate}). Same-unit conversion preserves the value.
 */
export function convert(value, from, to) {
  const error = validate(value, from, to);
  if (error !== null) {
    throw new Error(error);
  }

  if (from === to) {
    return value;
  }

  // Convert the input to Celsius, then from Celsius to the target unit.
  let celsius;
  switch (from) {
    case 'C':
      celsius = value;
      break;
    case 'F':
      celsius = ((value - 32) * 5) / 9;
      break;
    case 'K':
      celsius = value - 273.15;
      break;
    default:
      // validate() guarantees a supported unit; this cannot be reached.
      throw new Error('unsupported source unit');
  }

  switch (to) {
    case 'C':
      return celsius;
    case 'F':
      return (celsius * 9) / 5 + 32;
    case 'K':
      return celsius + 273.15;
    default:
      // validate() guarantees a supported unit; this cannot be reached.
      throw new Error('unsupported destination unit');
  }
}

// Entry point: starts the HTTP server on process.env.PORT (default 3000).
// See NFR2.
import { createApp } from './app.js';

const PORT = Number.parseInt(process.env.PORT ?? '3000', 10);

const app = createApp();

app.listen(PORT, () => {
  // eslint-disable-next-line no-console
  console.log(`Temperature converter listening on http://localhost:${PORT}`);
});

// Integration tests for the HTTP endpoints (FR1, FR2, FR4, FR5).
//
// These tests start the real HTTP server on an ephemeral port (port 0) and
// exercise it over the network via the built-in fetch API, so the routing,
// JSON parsing and absolute-zero validation in app.js are all covered.

import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';

import { createApp } from '../source/app.js';

let server;
let baseUrl;

before(async () => {
  server = createApp();
  await new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(0, '127.0.0.1', () => {
      const { port } = server.address();
      baseUrl = `http://127.0.0.1:${port}`;
      resolve();
    });
  });
});

after(async () => {
  await new Promise((resolve, reject) => {
    server.close((err) => (err ? reject(err) : resolve()));
  });
});

test('GET / serves an HTML page (FR1)', async () => {
  const res = await fetch(`${baseUrl}/`);
  assert.equal(res.status, 200);
  assert.match(res.headers.get('content-type'), /text\/html/);
  const html = await res.text();
  assert.match(html, /<html/i, 'page should contain an <html> element');
  assert.match(html, /<input/i, 'page should contain a numeric input');
  assert.match(html, /<select/i, 'page should contain unit selectors');
  assert.match(html, /<button/i, 'page should contain a submit button');
});

test('GET /health returns { status: "ok" } (FR5)', async () => {
  const res = await fetch(`${baseUrl}/health`);
  assert.equal(res.status, 200);
  const body = await res.json();
  assert.deepEqual(body, { status: 'ok' });
});

test('POST /api/convert converts C to F with 200 (FR2)', async () => {
  const res = await fetch(`${baseUrl}/api/convert`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ value: 100, from: 'C', to: 'F' }),
  });
  assert.equal(res.status, 200);
  const body = await res.json();
  assert.equal(body.value, 212);
  assert.equal(body.unit, 'F');
});

test('POST /api/convert converts K to C with 200 and does not round (FR2)', async () => {
  const res = await fetch(`${baseUrl}/api/convert`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ value: 273.15, from: 'K', to: 'C' }),
  });
  assert.equal(res.status, 200);
  const body = await res.json();
  assert.equal(body.value, 0);
  assert.equal(body.unit, 'C');
});

test('POST /api/convert preserves a decimal value (FR2)', async () => {
  const res = await fetch(`${baseUrl}/api/convert`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ value: 36.6, from: 'C', to: 'F' }),
  });
  assert.equal(res.status, 200);
  const body = await res.json();
  // 36.6 C = (36.6 * 9 / 5) + 32 = 97.88 F; must not be rounded to an integer.
  assert.ok(Math.abs(body.value - 97.88) < 1e-9);
  assert.equal(body.unit, 'F');
});

test('POST /api/convert returns 400 for missing fields (FR4)', async () => {
  const res = await fetch(`${baseUrl}/api/convert`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ value: 100, from: 'C' }),
  });
  assert.equal(res.status, 400);
  const body = await res.json();
  assert.ok(typeof body.error === 'string' && body.error.length > 0);
});

